export const createScene = async function (engine, canvas, BABYLON) {
  const scene = new BABYLON.Scene(engine);
  scene.clearColor = new BABYLON.Color4(0, 0, 0, 1);

  const isMobile = navigator.userAgentData ? navigator.userAgentData.mobile : /Android|iPhone|iPad|iPod/i.test(navigator.userAgent);
  const isARSupported = await BABYLON.WebXRSessionManager.IsSessionSupportedAsync("immersive-ar");

  const advancedTexture = BABYLON.GUI.AdvancedDynamicTexture.CreateFullscreenUI("UI");
  const mainContainer = new BABYLON.GUI.StackPanel();
  mainContainer.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_CENTER;
  advancedTexture.addControl(mainContainer);

  scene.createDefaultEnvironment({ createGround: false, createSkybox: false });

  // -----------------------------------------------------------
  // 1. 모델 및 루트 노드 설정 (피자와 햄버거 예시)
  // -----------------------------------------------------------
  const rootPizza = new BABYLON.TransformNode("rootPizza", scene);
  const rootBatman = new BABYLON.TransformNode("rootBatman", scene);
  rootPizza.setEnabled(false);
  rootBatman.setEnabled(false);

  const baseUrl = "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/";

  // 여러 모델을 비동기로 로드
  const [pizzaModel, batmanModel] = await Promise.all([
    BABYLON.SceneLoader.ImportMeshAsync("", baseUrl, "slice pizza.glb", scene),
    BABYLON.SceneLoader.ImportMeshAsync("", baseUrl, "batman in gotham ai.glb", scene),
  ]);

  // 피자 모델 설정
  pizzaModel.meshes[0].parent = rootPizza;
  pizzaModel.meshes[0].scaling.scaleInPlace(0.25);
  pizzaModel.meshes[0].rotate(BABYLON.Axis.Y, -Math.PI / 3, BABYLON.Space.LOCAL);

  // 두 번째 모델 설정 (예: 햄버거 또는 다른 모델)
  batmanModel.meshes[0].parent = rootBatman;
  batmanModel.meshes[0].scaling.scaleInPlace(0.025);
  batmanModel.meshes[0].rotate(BABYLON.Axis.Y, Math.PI, BABYLON.Space.LOCAL);

  // -----------------------------------------------------------
  // 2. XR 및 이미지 트래킹 설정
  // -----------------------------------------------------------
  const xr = await scene.createDefaultXRExperienceAsync({
    uiOptions: { sessionMode: "immersive-ar" },
  });

  const featuresManager = xr.baseExperience.featuresManager;

  const imageTracking = featuresManager.enableFeature(BABYLON.WebXRFeatureName.IMAGE_TRACKING, "latest", {
    images: [
      {
        src: baseUrl + "Images/pizza.png", // Index 0
        estimatedRealWorldWidth: 0.2,
      },
      {
        src: baseUrl + "Images/batman marker.png", // Index 1
        estimatedRealWorldWidth: 0.2,
      },
    ],
  });

  // 트래킹 업데이트 콜백
  imageTracking.onTrackedImageUpdatedObservable.add((image) => {
    if (image.index === 0) {
      rootPizza.setPreTransformMatrix(image.transformationMatrix);
      rootPizza.setEnabled(true);
    } else if (image.index === 1) {
      rootBatman.setPreTransformMatrix(image.transformationMatrix);
      rootBatman.setEnabled(true);
    }
  });

  // -----------------------------------------------------------
  // 3. UI 처리 (모바일/PC 분기)
  // -----------------------------------------------------------
  if (isARSupported) {
    const mobileText = new BABYLON.GUI.TextBlock();
    mobileText.text = "1. Tap XR button\n2. Scan Marker 1 or Marker 2";
    mobileText.color = "white";
    mobileText.fontSize = 20;
    mobileText.height = "80px";
    mainContainer.addControl(mobileText);

    xr.baseExperience.onStateChangedObservable.add((state) => {
      mainContainer.isVisible = state !== BABYLON.WebXRState.IN_XR;
    });
  } else if (!isMobile) {
    // PC 화면에 두 개의 마커를 표시
    const pcText = new BABYLON.GUI.TextBlock();
    pcText.text = "Scan these markers with your AR device";
    pcText.color = "cyan";
    pcText.fontSize = 24;
    pcText.height = "50px";
    mainContainer.addControl(pcText);

    const imageContainer = new BABYLON.GUI.StackPanel("imageContainer");
    imageContainer.isVertical = true;
    mainContainer.addControl(imageContainer);

    const addMarkerUI = (name, src) => {
      const stack = new BABYLON.GUI.StackPanel();
      stack.width = "350px";

      const img = new BABYLON.GUI.Image(name, src);
      img.width = "300px";
      img.height = "300px";
      img.paddingLeft = "10px";
      img.paddingRight = "10px";

      const txt = new BABYLON.GUI.TextBlock();
      txt.text = name;
      txt.color = "white";
      txt.height = "30px";

      stack.addControl(img);
      stack.addControl(txt);
      imageContainer.addControl(stack);
    };

    addMarkerUI("Marker 1 (Pizza)", baseUrl + "Images/pizza.png");
  }

  return scene;
};
